{"packet_id":"D076-01","doc_id":"D076","jurisdiction":"San Diego, CA","category":"algorithmic_rent_setting","lifecycle":"pending_bill","title":"Prohibition of Anti-Competitive Automated Rent Price-Fixing Ordinance","requirement":"Would ban selling, licensing, or providing an algorithmic device that uses nonpublic competitor data to advise landlords on rental rates or occupancy levels, and ban landlords from using such a device to set rents or occupancy.","key_value":"$1,000 civil penalty per violation","coverage_conditions":"Residential rental property in the City of San Diego; landlords and any person who sells, licenses or provides algorithmic devices.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":"Software publishing reports from aggregated historical nonpublic competitor data more than 90 days old or from public information, without recommending future rates; software setting rates or income limits under affordable housing program guidelines.","penalty":"A tenant may seek injunctive relief, damages, or civil penalties up to $1,000 per violation; a prevailing tenant recovers costs and reasonable attorney's fees.","effective_date":null,"valid_through":null,"citation":"San Diego Mun. Code §§98.1101–98.1104","quoted_span":"(a) It is unlawful for a person to sell, license, or otherwise provide an
algorithmic device to a landlord.
(b) It is unlawful for a landlord to use an algorithmic device to set rental rates
or occupancy levels for residential rental property.","interaction":null,"relations":[],"confidence":0.6,"conflict_flag":false,"conflict_note":null}
